adcs_vec3_t h_total = {0, 0, 0};
double energy_total = 0.0;
double max_abs_speed = -1.0;
size_t fastest_idx = SIZE_MAX;
adcs_vec3_t axis_normed;
double abs_speed;
size_t i;

if (wheels == NULL || momentum == NULL || momentum_norm == NULL || 
    energy == NULL || fastest == NULL) {
    return ADCS_E_NULL;
}

if (count != 4) {
    *momentum = (adcs_vec3_t){0, 0, 0};
    *momentum_norm = 0.0;
    *energy = 0.0;
    *fastest = SIZE_MAX;
    return ADCS_E_RANGE;
}

for (i = 0; i < count; i++) {
    const adcs_wheel_t *w = &wheels[i];

    if (!isfinite(w->inertia_kg_m2) || w->inertia_kg_m2 <= 0.0) {
        *momentum = (adcs_vec3_t){0, 0, 0};
        *momentum_norm = 0.0;
        *energy = 0.0;
        *fastest = SIZE_MAX;
        return ADCS_E_RANGE;
    }

    if (!isfinite(w->speed_rad_s)) {
        *momentum = (adcs_vec3_t){0, 0, 0};
        *momentum_norm = 0.0;
        *energy = 0.0;
        *fastest = SIZE_MAX;
        return ADCS_E_RANGE;
    }

    if (adcs_vec3_normalize(&w->axis_body, ADCS_EPS_NORM, &axis_normed) != ADCS_OK) {
        *momentum = (adcs_vec3_t){0, 0, 0};
        *momentum_norm = 0.0;
        *energy = 0.0;
        *fastest = SIZE_MAX;
        return ADCS_E_RANGE;
    }

    adcs_vec3_t term = adcs_vec3_scale(&axis_normed, w->inertia_kg_m2 * w->speed_rad_s);
    h_total = adcs_vec3_add(&h_total, &term);

    energy_total += 0.5 * w->inertia_kg_m2 * w->speed_rad_s * w->speed_rad_s;

    abs_speed = fabs(w->speed_rad_s);
    if (max_abs_speed < 0.0 || abs_speed > max_abs_speed) {
        max_abs_speed = abs_speed;
        fastest_idx = i;
    }
}

*momentum = h_total;
*momentum_norm = adcs_vec3_norm(&h_total);
*energy = energy_total;
*fastest = fastest_idx;

return ADCS_OK;

